/* ===== domain helpers ===== */
const MYROLE=()=>S.role==='provider'?'provider':'vendor';
const ownerId=()=>S.role==='provider'?S.prov.sid:S.vend.bid;
const RT=n=>(S.role==='provider'?'s':'v')+n.slice(1);
const D=()=>S.db;
const biz=id=>D().biz.find(b=>b.id===id)||D().svc.find(s=>s.id===id),svc=id=>D().svc.find(s=>s.id===id),prod=id=>D().products.find(p=>p.id===id),rider=id=>D().riders.find(r=>r.id===id),order=id=>D().orders.find(o=>o.id===id);
const ent=id=>!id?null:/-sv\d+$/.test(id)?svcObj(id):id[0]==='b'?biz(id):id[0]==='s'?svc(id):id[0]==='r'?rider(id):id[0]==='p'?prod(id):null;
const rad=x=>x*Math.PI/180;
const km=(a,b)=>{const R=6371,dl=rad(b.lat-a.lat),dg=rad(b.lng-a.lng),x=Math.sin(dl/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dg/2)**2;return 2*R*Math.asin(Math.sqrt(x))};
const myPos=()=>({lat:S.loc.lat,lng:S.loc.lng});
const dist=x=>km(myPos(),x);
const f12=s=>{const[h,m]=s.split(':').map(Number);return((h%12)||12)+':'+String(m).padStart(2,'0')+' '+(h<12?'AM':'PM')};
function openState(x){if(x.closedNow)return{open:false,label:t('Temporarily closed')};const n=new Date(),h=x.hours[n.getDay()];if(!h)return{open:false,label:t('Closed today')};const m=n.getHours()*60+n.getMinutes(),o=T(h[0]),c=T(h[1]);if(m>=o&&m<c)return{open:true,label:t('Open now'),sub:t('Closes')+' '+f12(h[1])};return{open:false,label:m<o?t('Opens at')+' '+f12(h[0]):t('Closed')}}
const addrPos=()=>{const a=S.addrs.find(x=>x.id===S.selAddr);return S.user&&a?{lat:a.lat,lng:a.lng}:myPos()};
const feeFor=(b,d)=>{if(b.del.mode==='self')return +b.del.fee||0;const s=D().cfg.slabs.find(x=>d<=x.upto);return s?s.fee:D().cfg.slabs[D().cfg.slabs.length-1].fee};
const riderEarn=d=>Math.round(D().cfg.riderBase+D().cfg.riderPerKm*d);
const delivInfo=(b,pos)=>{const d=km(pos||addrPos(),b);return{ok:d<=b.del.radius,d,fee:feeFor(b,d)}};
const OST={placed:['Placed','--st-placed','◔'],accepted:['Accepted','--st-accepted','✓'],preparing:['Preparing','--st-preparing','◐'],ready:['Ready','--st-ready','▣'],out:['Out for delivery','--st-out','➜'],delivered:['Delivered','--st-delivered','✔'],pickedup:['Picked up','--st-delivered','✔'],cancelled:['Cancelled','--st-cancelled','✕'],refunded:['Refunded','--st-refunded','↺']};
const stBadge=(s,o)=>{const x=OST[s]||['?','--muted','•'];const lab=(s==='ready'&&o&&o.mode==='pickup')?'Ready for pickup':x[0];return `<span class="badge st" style="--c:var(${x[1]})"><span aria-hidden="true">${x[2]}</span>${esc(t(lab))}</span>`};
const AP={pending:['Pending','--ap-pending','⏳'],approved:['Approved','--ap-approved','✓'],rejected:['Rejected','--ap-rejected','✕'],suspended:['Suspended','--ap-suspended','⏸'],inactive:['Inactive','--ap-inactive','○'],changes:['Changes requested','--ap-pending','✎']};
const apBadge=s=>{const x=AP[s]||AP.pending;return `<span class="badge st" style="--c:var(${x[1]})"><span aria-hidden="true">${x[2]}</span>${esc(t(x[0]))}</span>`};
const flowOf=o=>o.mode==='pickup'?['placed','accepted','ready','pickedup']:['placed','accepted','preparing','ready','out','delivered'];
const orderTotal=o=>Math.max(0,o.subtotal+o.delivery+o.fee-o.discount);
const catName=id=>nm(catOf(id)),areaName=id=>nm(areaOf(id));
/* notifications + audit */
function notify(role,title,body,link,type='sys'){const l=D().notifs[role];if(l)l.unshift({id:rid('n'),type,title,body,ts:Date.now(),read:false,link:link||'',})}
function audit(action,detail,before,after){D().audit.unshift({id:rid('a'),ts:Date.now(),actor:S.role==='super'?'Super Admin':(D().admins.find(a=>a.id===S.adminId)||{}).name||'Admin',action,detail,before,after})}
function setStatus(o,s){o.status=s;o.history.push({s,ts:Date.now()});const lab=(OST[s]||[s])[0];
 if(o.uid==='u1')notify('cust','Order '+o.id+': '+lab,biz(o.bid).name.en+' updated your order.','order-'+o.id,'order');
 if(['out','delivered','pickedup'].includes(s))notify('vendor','Order '+o.id+': '+lab,'Status updated.','vorder-'+o.id,'order');save()}
/* cart */
const cartCount=()=>S.cart.filter(c=>!c.saved).reduce((a,c)=>a+c.qty,0);
function cartGroups(){const g={};S.cart.filter(c=>!c.saved).forEach(c=>{const p=prod(c.pid);if(!p)return;(g[p.bid]=g[p.bid]||[]).push({...c,p})});return Object.entries(g).map(([bid,lines])=>({bid,b:biz(bid),lines,sub:lines.reduce((a,l)=>a+l.p.price*l.qty,0)}))}
function offerPrice(p){const o=D().offers.find(o=>o.bid===p.bid&&o.status==='active'&&(o.pids.includes(p.id))&&Date.now()<o.to);if(!o)return p.price;return o.type==='percent'?Math.round(p.price*(1-o.value/100)):o.type==='flat'?Math.max(1,p.price-o.value):p.price}
/* ===== overlays ===== */
let CB={};
function closeSheet(){const r=$('#sheetRoot');if(r)r.remove();document.body.style.overflow=''}
function sheet(html,o={}){closeSheet();const d=document.createElement('div');d.id='sheetRoot';d.innerHTML=`<div class="scrim" data-act="closeSheet"></div><div class="sheet ${o.wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(o.label||'')}"><div class="grab"></div>${html}</div>`;document.body.appendChild(d);const f=d.querySelector('input:not([type=hidden]),button.btn,button');if(f&&!o.nofocus)setTimeout(()=>f.focus({preventScroll:true}),30)}
function toast(m,icn='check'){const w=$('#toasts');const e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.innerHTML=ic(icn,18)+'<span>'+esc(m)+'</span>';w.appendChild(e);setTimeout(()=>e.remove(),3200)}
function confirmBox(title,msg,ok,fn,danger){const id=rid('c');CB[id]=fn;sheet(`<div class="stack"><h3>${esc(title)}</h3><p class="t2">${esc(msg)}</p><div class="row"><button class="btn g grow" data-act="closeSheet">${t('Cancel')}</button><button class="btn ${danger?'d':'p'} grow" data-act="cb" data-id="${id}">${esc(ok)}</button></div></div>`,{label:title})}
/* ===== shared ui bits ===== */
const empty=(emoji,title,msg,cta)=>`<div class="state"><div class="ill" aria-hidden="true">${emoji}</div><h3>${esc(t(title))}</h3><p>${esc(t(msg))}</p>${cta||''}</div>`;
const errState=(msg)=>`<div class="state" role="alert"><div class="ill" aria-hidden="true">⚠️</div><h3>${t('Something went wrong')}</h3><p>${esc(msg?t(msg):t('Please check your connection and try again.'))}</p><button class="btn p" data-act="retry">${ic('refresh',18)} ${t('Try again')}</button></div>`;
const noPerm=(msg)=>`<div class="state"><div class="ill" aria-hidden="true">🔒</div><h3>${t('You don’t have permission')}</h3><p>${esc(t(msg||'This section is not available for your role. Ask a Super Admin for access.'))}</p><button class="btn o" data-act="demo">${t('Switch demo role')}</button></div>`;
const skel=(n=4)=>`<div class="stack" aria-busy="true" aria-label="Loading">${'<div class="skel" style="height:22px;width:55%"></div><div class="grid g2"><div class="skel" style="height:110px"></div><div class="skel" style="height:110px"></div></div><div class="skel" style="height:70px"></div>'.repeat(Math.ceil(n/3))}</div>`;
const sec=(title,link,lt)=>`<div class="sec"><h2>${t(title)}</h2>${link?`<a class="btn t sm" href="#${link}">${t(lt||'See all')} ${ic('cr',16)}</a>`:''}</div>`;
const kpi=(l,v,d,up=true)=>`<div class="card kpi"><span class="l">${t(l)}</span><span class="v">${v}</span>${d?`<span class="dl ${up?'up':'dn'}">${up?'▲':'▼'} ${d}</span>`:''}</div>`;
const alertBox=(kind,msg,icn)=>`<div class="alert ${kind}" role="${kind==='bad'?'alert':'status'}">${ic(icn||(kind==='ok'?'check':kind==='bad'?'alert':'info'),20)}<div>${msg}</div></div>`;
const openBadge=x=>{const o=openState(x);return `<span class="badge ${o.open?'ok':'bad'}">${o.open?'●':'○'} ${esc(o.label)}</span>`};
const vBadge=()=>`<span class="badge sec" title="${t('Verified')}">${ic('shield',13)} ${t('Verified')}</span>`;
const delivBadge=b=>{const d=delivInfo(b);return d.ok?`<span class="badge ok">${ic('truck',13)} ${t('Delivers to you')}</span>`:`<span class="badge neu">${ic('pin',13)} ${t('Pickup only here')}</span>`};
const bizCard=(b,grid)=>{const d=dist(b);return `<a class="card hover biz ${grid?'':'row'}" href="#biz-${b.id}">${art(b.emoji,b.hue,grid?'f':'')}<div class="body"><div class="t"><span class="truncate">${esc(nm(b.name))}</span></div><div class="meta"><span>${esc(catName(b.cat))}</span>·<span>${esc(areaName(b.area))}</span></div><div class="meta">${stars(b.rating)}<b>${b.rating.toFixed(1)}</b><span>(${b.rc})</span>·<span>${d.toFixed(1)} km</span></div><div class="row wrap-r" style="gap:6px">${openBadge(b)}${b.verified?vBadge():''}${delivBadge(b)}</div></div></a>`};
const svcCard=(s,grid)=>{const d=dist(s);return `<a class="card hover biz ${grid?'':'row'}" href="#svc-${s.id}">${art(s.emoji,s.hue,grid?'f':'')}<div class="body"><div class="t"><span class="truncate">${esc(nm(s.name))}</span></div><div class="meta"><span>${esc(catName(s.cat))}</span>·<span>${esc(areaName(s.area))}</span></div><div class="meta">${stars(s.rating)}<b>${s.rating.toFixed(1)}</b><span>(${s.rc})</span>·<span>${d.toFixed(1)} km</span></div>${(s.ssubs||[]).length?`<div class="row wrap-r" style="gap:4px">${s.ssubs.slice(0,3).map(x=>`<span class="badge neu">${esc(subLabel(x))}</span>`).join('')}</div>`:''}<div class="row wrap-r" style="gap:6px">${openBadge(s)}${s.verified?vBadge():''}<span class="badge info">${ic('chat',13)} ${t('Enquiry')}</span></div></div></a>`};
const prodCard=p=>{const op=offerPrice(p),b=biz(p.bid),out=!p.avail||p.stock<=0;const disc=p.mrp>op?Math.round((1-op/p.mrp)*100):0;return `<a class="card hover pcard" href="#prod-${p.id}">${art(p.emoji,p.hue)}<div class="body"><div class="t">${esc(nm(p.name))}</div><div class="xs muted truncate">${esc(nm(b.name))} · ${esc(p.unit)}</div><div><span class="price">${inr(op)}</span>${p.mrp>op?`<span class="mrp">${inr(p.mrp)}</span><span class="off">${disc}% ${t('OFF')}</span>`:''}</div>${out?`<span class="badge bad">${t('Out of stock')}</span>`:p.stock<=p.low?`<span class="badge warn">${t('Only')} ${p.stock} ${t('left')}</span>`:''}</div></a>`};
const revCard=(r,mine)=>`<div class="card pad stack" style="gap:8px"><div class="row between"><div class="row"><div class="art" style="width:38px;height:38px;border-radius:50%;font-size:1rem;--h:${(r.name.charCodeAt(0)*7)%360}">${esc(r.name[0])}</div><div><b>${esc(r.name)}</b><div class="xs muted">${ago(r.ts)}</div></div></div>${stars(r.rating)}</div><p>${esc(r.text)}</p>${r.tags&&r.tags.length?`<div class="row wrap-r" style="gap:6px">${r.tags.map(x=>`<span class="badge neu">${esc(x)}</span>`).join('')}</div>`:''}${r.reply?`<div class="alert info"><div><b>${t('Reply from owner')}:</b> ${esc(r.reply)}</div></div>`:''}<div class="row">${mine==='none'?'':mine?`<button class="btn t sm" data-act="editReview" data-id="${r.id}">${ic('edit',16)} ${t('Edit')}</button><button class="btn t sm" data-act="delReview" data-id="${r.id}">${ic('trash',16)} ${t('Delete')}</button>`:`<button class="btn t sm" data-act="helpful" data-id="${r.id}">👍 ${t('Helpful')} (${r.helpful||0})</button><button class="btn t sm" data-act="reportReview" data-id="${r.id}">${ic('flag',16)} ${t('Report')}</button>`}${r.status==='pending'?'<span class="badge warn">'+t('Pending moderation')+'</span>':''}</div></div>`;
function ratingBreak(list){const n=list.length||1,c=[0,0,0,0,0,0];list.forEach(r=>c[r.rating]++);const avg=list.length?list.reduce((a,r)=>a+r.rating,0)/list.length:0;return `<div class="row" style="align-items:flex-start;gap:18px"><div class="center"><div class="price" style="font-size:2.2rem">${avg.toFixed(1)}</div>${stars(avg,16)}<div class="xs muted">${list.length} ${t('reviews')}</div></div><div class="grow stack" style="gap:6px">${[5,4,3,2,1].map(i=>`<div class="rb"><span>${i}★</span><div class="tr"><i style="width:${c[i]/n*100}%"></i></div><span>${c[i]}</span></div>`).join('')}</div></div>`}
const tbl=(cols,rows,o={})=>`<div class="table-w"><table class="tbl resp"><thead><tr>${cols.map(c=>`<th scope="col">${t(c)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((c,i)=>`<td data-l="${esc(t(cols[i]))}">${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}">${empty('📭','Nothing here yet','Items will appear here.')}</td></tr>`}</tbody></table></div>`;
const field=(label,name,v='',o={})=>`<div class="field"><label for="f_${name}">${t(label)}${o.req?' *':''}</label>${o.type==='textarea'?`<textarea class="input" id="f_${name}" name="${name}" ${o.req?'required':''} placeholder="${esc(t(o.ph||''))}">${esc(v)}</textarea>`:o.type==='select'?`<select class="input" id="f_${name}" name="${name}">${o.opts.map(x=>`<option value="${esc(x[0])}" ${String(x[0])===String(v)?'selected':''}>${esc(t(x[1]))}</option>`).join('')}</select>`:`<input class="input" id="f_${name}" name="${name}" type="${o.type||'text'}" value="${esc(v)}" ${o.req?'required':''} ${o.min!=null?`min="${o.min}"`:''} ${o.step?`step="${o.step}"`:''} ${o.pattern?`pattern="${o.pattern}"`:''} inputmode="${o.im||''}" placeholder="${esc(t(o.ph||''))}" autocomplete="${o.ac||'off'}">`}${o.hint?`<span class="hint">${t(o.hint)}</span>`:''}</div>`;
const toggle=(name,on,label,act)=>`<label class="row between" style="min-height:44px"><span>${t(label)}</span><span class="toggle"><input type="checkbox" ${on?'checked':''} data-chg="${act||'tg'}" data-k="${name}"><span></span></span></label>`;
const uploader=(label)=>`<div class="drop"><div>${ic('camera',22)}</div><div class="small">${t(label||'Tap to add photo')}</div><button type="button" class="btn g sm" data-act="fakeUpload" style="margin-top:6px">${ic('upload',16)} ${t('Choose file')}</button></div>`;
/* ===== maps (schematic SVG, no external tiles) ===== */
const MAP={w:360,h:300,kmw:8};
const mapXY=(p,c)=>{const pxkm=MAP.w/MAP.kmw,c0=c||CENTER;return{x:MAP.w/2+(p.lng-c0.lng)*111*Math.cos(rad(c0.lat))*pxkm,y:MAP.h/2-(p.lat-c0.lat)*111*pxkm}};
const mapLL=(x,y,c)=>{const pxkm=MAP.w/MAP.kmw,c0=c||CENTER;return{lat:c0.lat-(y-MAP.h/2)/pxkm/111,lng:c0.lng+(x-MAP.w/2)/pxkm/111/Math.cos(rad(c0.lat))}};
function mapSvg(id,pins=[],o={}){const me=mapXY(o.me||myPos(),o.center);const base=`<rect width="360" height="300" fill="none"/><path d="M-10 240 C80 210 140 270 230 230 S340 200 380 215" stroke="#9CC9E8" stroke-width="16" fill="none" opacity=".8"/><path d="M0 150 H360 M0 90 H360 M0 215 H360 M90 0 V300 M180 0 V300 M265 0 V300" stroke="#fff" stroke-width="7" opacity=".85"/><path d="M40 0 L330 300" stroke="#fff" stroke-width="5" opacity=".7"/><path d="M0 40 H360" stroke="#7a7a7a" stroke-width="2" stroke-dasharray="6 4" opacity=".6"/><rect x="200" y="100" width="50" height="40" rx="8" fill="#B7D9A8" opacity=".7"/><rect x="40" y="170" width="46" height="34" rx="8" fill="#B7D9A8" opacity=".7"/>${AREAS.map(a=>{const p=mapXY(a,o.center);return `<text x="${p.x}" y="${p.y+22}" font-size="7.5" text-anchor="middle" fill="#6b5b45" opacity=".9">${esc(nm(a))}</text>`}).join('')}`;
 const rad_=o.radius?`<circle cx="${me.x}" cy="${me.y}" r="${o.radius*MAP.w/MAP.kmw}" fill="${'#C2410C'}" fill-opacity=".08" stroke="#C2410C" stroke-dasharray="5 4"/>`:'';
 const pp=pins.map(p=>{const q=mapXY(p,o.center);if(q.x<-10||q.x>370||q.y<-10||q.y>310)return'';const sel=o.sel===p.id;return `<g class="pin" tabindex="0" role="button" aria-label="${esc(nm(p.name))}" data-act="mapPin" data-id="${p.id}" transform="translate(${q.x},${q.y})"><circle r="${sel?15:12}" fill="${sel?'#C2410C':'#fff'}" stroke="#C2410C" stroke-width="2.5"/><text y="5" text-anchor="middle" font-size="${sel?15:13}">${p.emoji}</text></g>`}).join('');
 const youEl=o.noMe?'':`<g transform="translate(${me.x},${me.y})"><circle r="14" fill="#1D4ED8" fill-opacity=".18"><animate attributeName="r" values="8;18;8" dur="2.4s" repeatCount="indefinite"/></circle><circle r="6" fill="#1D4ED8" stroke="#fff" stroke-width="2.5"/></g>`;
 return `<div class="map" id="${id}"><svg viewBox="0 0 360 300" role="img" aria-label="${t('Map of nearby places')}">${base}${rad_}${pp}${youEl}${o.drag?`<g id="dragpin" transform="translate(${mapXY(o.drag,o.center).x},${mapXY(o.drag,o.center).y})"><path d="M0 0 C-14-16-14-34 0-34 C14-34 14-16 0 0z" fill="#C2410C" stroke="#fff" stroke-width="2"/><circle cy="-22" r="5" fill="#fff"/></g>`:''}</svg></div>`}
